{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/hero-split.json
    A split hero: a badge, the heading, a lead, an extra under it and one or two actions, beside the media. Axes: extra (stats: three figures, avatars: faces and a proof line, minis: two small feature cards, quote: a quote over three figures, none), media (picture, card: a floating card on the picture, grid: four pictures with captions, plans: two plan cards on the picture), mediaSide, tone.
    Props (p): id, title, lead, badge, level, actions, content, extra, media, mediaSide, tone, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_lead = (p.lead ?? '') -%}
{%- set v_badge = (p.badge ?? '') -%}
{%- set v_level = (p.level ?? 1) -%}
{%- set v_actions = (p.actions ?? null) -%}
{%- set v_content = (p.content ?? null) -%}
{%- set v_extra = (p.extra ?? 'stats') -%}
{%- set v_media = (p.media ?? 'picture') -%}
{%- set v_mediaSide = (p.mediaSide ?? 'end') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
