  {{ include('blocks/hero-split-media.html.twig', {'p': {'content': v_content, 'alt': v_title, 'media': v_media}}, with_context = false) }}
{%- endset -%}
{%- set c_2 -%}
  {{ include('blocks/hero-split-extras.html.twig', {'p': {'content': v_content, 'extra': v_extra}}, with_context = false) }}
